def relief(T, ax):   # 축 방향 층마다 덮인 영역(첫 고리 = 바깥, 나머지 = 구멍)을 그 층 두께만큼 밀어 쌓기
    pl, sg = {'x': ('YZ', 1), 'y': ('XZ', -1), 'z': ('XY', 1)}[ax]; r = None
    for h0, h1, PS in T:
        for W in PS:
            w = cq.Workplane(pl, origin=cq.Vector(*[(h0 if k == ax else 0) for k in "xyz"]))
            for P in W: w = w.polyline(P).close()
            s = w.extrude(sg * (h1 - h0)); r = s if r is None else r.union(s)
    return r
r = relief(TA, 'y').intersect(relief(TB, 'x'))
